SourceCode.Declaration:
/// <summary>
/// Extension of <c>BOMCalcTable</c> to trigger the BOM calculation completed business event.
/// </summary>
[ExtensionOf(tableStr(BOMCalcTable))]
final class AAXBOMCalcTable_Table_Extension
{
}

Method.Source:
/// <summary>
/// Triggers the BOM calculation completed business event when a new BOM calculation record is created.
/// </summary>
void insert()
{
    next insert();

    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(AAXBOMCalcCompletedBusinessEvent)))
    {
        AAXBOMCalcCompletedBusinessEvent::newFromBOMCalcTable(this).send();
    }
}
